#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }
    char *end1, *end2;
    long mode = strtol(argv[1], &end1, 10);
    long limit = strtol(argv[2], &end2, 10);
    if (*end1 != '\0' || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (limit > 100000) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    const double C = 1.0; // constant used in the original binary
    double sum = 0.0;
    switch (mode) {
        case 1: // sum of 1/(i^2)
            for (long i = 1; i <= limit; ++i) {
                sum += C / (i * i);
            }
            break;
        case 2: // harmonic series sum 1/i
            for (long i = 1; i <= limit; ++i) {
                sum += C / i;
            }
            break;
        case 3: // constant + harmonic series
            sum = C;
            for (long i = 1; i <= limit; ++i) {
                sum += C / i;
            }
            break;
        default:
            puts("BAD_MODE");
            return 0;
    }
    printf("%.6f\n", sum);
    return 0;
}
